from __future__ import annotations

import ipaddress
from collections.abc import Iterable

from app.models.mapping import Mapping
from app.schemas.mapping import normalize_domain

_HEADER = """# ===================================================
# AUTO-GENERATED BY DNS MANAGER
# DO NOT EDIT MANUALLY
# ===================================================
"""


def _validated_proxy_ip(value: str) -> str:
    try:
        return str(ipaddress.ip_address(value.strip()))
    except ValueError as exc:
        raise ValueError("invalid internal proxy IP") from exc


def render_dnsmasq_config(mappings: Iterable[Mapping], internal_proxy_ip: str) -> str:
    proxy_ip = _validated_proxy_ip(internal_proxy_ip)
    domains: list[str] = []

    for mapping in mappings:
        if not mapping.enabled:
            continue
        try:
            domain = normalize_domain(mapping.domain)
        except ValueError as exc:
            raise ValueError("invalid domain") from exc
        domains.append(domain)

    lines = [_HEADER.rstrip(), ""]
    lines.extend(f"address=/{domain}/{proxy_ip}" for domain in sorted(set(domains)))
    return "\n".join(lines).rstrip() + "\n"
